el('helpBtn').addEventListener('click',()=>el('helpDialog').showModal());['closeHelp','closeHelp2'].forEach(id=>el(id).addEventListener('click',()=>el('helpDialog').close()));
el('searchToggle').addEventListener('click',()=>{el('searchArea').classList.toggle('hidden');if(!el('searchArea').classList.contains('hidden'))el('globalSearch').focus()});el('searchClose').addEventListener('click',()=>el('searchArea').classList.add('hidden'));
el('globalSearch').addEventListener('input',e=>{groupFilter='Todas';route='library';el('currentPage').textContent='Biblioteca';library(e.target.value)});// A tela de abertura aparece a cada abertura do arquivo, sem apagar a escolha ou os registros anteriores.
function beginExperience(){document.body.classList.add('journey-started');el('app').removeAttribute('aria-hidden');route='home';navigate('home');const t=el('screen').querySelector('.hero h1');if(t){t.setAttribute('tabindex','-1');t.focus({preventScroll:true})}}
el('startJourney').addEventListener('click',beginExperience);
el('welcomeModes').addEventListener('click',()=>el('modalitiesDialog').showModal());
el('modalitiesInfo').addEventListener('click',()=>el('modalitiesDialog').showModal());
el('closeModalities').addEventListener('click',()=>el('modalitiesDialog').close());
el('modalitiesDialog').addEventListener('click',e=>{if(e.target===el('modalitiesDialog'))el('modalitiesDialog').close();const m=e.target.closest('[data-dialog-mode]');if(!m)return;mode=m.dataset.dialogMode;localStorage.setItem('jornadaModeV4',mode);el('modalitiesDialog').close();if(!document.body.classList.contains('journey-started')){beginExperience()}else{navigate(mode==='teacher'?'home':'personal')}});
// Movimento leve dentro da faixa; a faixa em si participa da rolagem normal.
let bannerRAF=0;
function updateBanner(){bannerRAF=0;if(window.matchMedia('(prefers-reduced-motion: reduce)').matches)return;const heroNode=el('screen').querySelector('.hero');if(!heroNode)return;const rect=heroNode.getBoundingClientRect();const offset=Math.max(-90,Math.min(90,-rect.top*.17));heroNode.style.setProperty('--hero-parallax',`${offset.toFixed(1)}px`)}
window.addEventListener('scroll',()=>{if(!bannerRAF)bannerRAF=requestAnimationFrame(updateBanner)},{passive:true});
el('closeReports').addEventListener('click',()=>el('reportsDialog').close());
el('reportsDialog').addEventListener('click',e=>{if(e.target===el('reportsDialog'))el('reportsDialog').close();const btn=e.target.closest('[data-export-docx]');if(btn)doDocx(btn.dataset.exportDocx);if(e.target.id==='downloadJsonBackup')downloadJson()});
